// Poll GitHub for new PRs on nabitllc repos and post to Discord #pr-reviews
// ONE message per PR, listing ALL linked MC issues (grouped by pr_url)
const GH_TOKEN = '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';
const DISCORD_BOT_TOKEN = 'MTQ4NjA0MTQ3MTUwNDM1MTMxMw.GoiBGW.VS2nGK2X1LMjMjkOBL9NqrOVeUdZfbGo9HdAyo';
const PR_CHANNEL = '1487826368170299592'; // #pr-reviews
const MC_API = 'http://localhost:3000/api/issues';
const REPOS = ['nabitllc/kaos-mission-control', 'nabitllc/vespera'];

// $getWorkflowStaticData is the correct n8n code-node API (not this.getWorkflowStaticData)
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenPRs) staticData.seenPRs = {};

const now = Date.now();
// Prune entries older than 30 days
for (const [key, ts] of Object.entries(staticData.seenPRs)) {
  if (now - ts > 30 * 24 * 60 * 60 * 1000) delete staticData.seenPRs[key];
}

const ghHeaders = {
  'Authorization': 'Bearer ' + GH_TOKEN,
  'Accept': 'application/vnd.github+json',
  'X-GitHub-Api-Version': '2022-11-28',
  'User-Agent': 'KAOS-n8n-agent'
};

const TYPE_EMOJI = {
  feature: '\u2728',
  task: '\ud83d\udccb',
  bug: '\ud83d\udc1b',
  epic: '\ud83c\udfd4\ufe0f',
  ops: '\u2699\ufe0f',
  research: '\ud83d\udd2c'
};

function statusSuffix(status) {
  if (['approved', 'released', 'closed'].includes(status)) return ' [' + status + ']';
  if (['in_review', 'code_review'].includes(status)) return ' [in review]';
  return '';
}

function toEST(isoStr) {
  const d = new Date(isoStr);
  return d.toLocaleString('en-US', {
    timeZone: 'America/New_York',
    month: 'short', day: 'numeric',
    hour: '2-digit', minute: '2-digit', hour12: true
  }) + ' EST';
}

const results = [];

// Fetch all MC issues once, group by pr_url
let issuesByPR = {};
try {
  const allIssues = await helpers.httpRequest({
    method: 'GET',
    url: MC_API,
    headers: { 'Content-Type': 'application/json' }
  });
  for (const issue of allIssues) {
    if (issue.pr_url) {
      if (!issuesByPR[issue.pr_url]) issuesByPR[issue.pr_url] = [];
      issuesByPR[issue.pr_url].push(issue);
    }
  }
} catch(e) {
  // Proceed without issue linking if MC API unavailable
}

for (const repo of REPOS) {
  let prs;
  try {
    prs = await helpers.httpRequest({
      method: 'GET',
      url: 'https://api.github.com/repos/' + repo + '/pulls?state=open&per_page=20&sort=created&direction=desc',
      headers: ghHeaders
    });
  } catch(e) {
    results.push({ repo, error: String(e) });
    continue;
  }

  for (const pr of prs) {
    const prKey = repo + '#' + pr.number;
    if (staticData.seenPRs[prKey]) continue; // Already notified - skip

    const linkedIssues = issuesByPR[pr.html_url] || [];
    const ts = toEST(pr.created_at);

    // Build ONE message for this PR
    let msg = '\ud83d\udd00 **PR #' + pr.number + '** \u2014 ' + pr.title.slice(0, 80) + '\n';
    msg += 'Branch: `' + pr.head.ref + '` \u2192 `' + pr.base.ref + '`\n';
    msg += 'Author: ' + pr.user.login + ' | ' + ts + '\n';

    if (linkedIssues.length > 0) {
      msg += '\n**Issues in this PR:**\n';
      for (const issue of linkedIssues) {
        const emoji = TYPE_EMOJI[issue.type] || '\ud83d\udccb';
        const key = issue.task_key || issue.id.slice(0, 8);
        msg += emoji + ' **' + key + '** \u2014 ' + issue.title.slice(0, 60) + statusSuffix(issue.status) + '\n';
      }
    }

    msg += '\n<' + pr.html_url + '>';

    // Post to Discord using Bot token via helpers.httpRequest (not execSync)
    try {
      await helpers.httpRequest({
        method: 'POST',
        url: 'https://discord.com/api/v10/channels/' + PR_CHANNEL + '/messages',
        headers: {
          'Authorization': 'Bot ' + DISCORD_BOT_TOKEN,
          'Content-Type': 'application/json'
        },
        body: { content: msg }
      });
      // Mark PR as notified ONLY after successful Discord post
      staticData.seenPRs[prKey] = now;
      results.push({ repo, pr: pr.number, title: pr.title, linkedIssues: linkedIssues.length, action: 'posted' });
    } catch(e) {
      results.push({ repo, pr: pr.number, error: 'Discord post failed: ' + String(e) });
    }
  }
}

return [{ json: { processed: results.length, results, timestamp: new Date().toISOString() } }];
